function optionsFor(f){var a=[];if(f.options)a=typeof f.options==='function'?f.options():f.options;if(f.source==='clients')a=(pack.clients||[]).map(function(x){return[x.id,x.name]});if(f.source==='cases')a=(pack.cases||[]).map(function(x){return[x.id,x.subject+' — '+caseNo(x)]});if(f.source==='users')a=(pack.users_brief||[]).map(function(x){return[x.id,x.full_name]});if(f.source==='stages')a=(pack.case_stages||[]).filter(function(x){return!f.caseId||String(x.case_id)===String(f.caseId)}).map(function(x){return[x.id,x.degree+' — '+(x.case_number||'بدون رقم')]});return a.map(function(x){return Array.isArray(x)?x:[x,x]})}
