function schemaFields(entity,caseId){return SCHEMAS[entity].fields.map(function(x){return{name:x[0],label:x[1],type:x[2]||'text',required:!!x[3],options:x[4],source:x[5],caseId:caseId}})}
function fieldHtml(f,v){var val=v==null?'':v;if(f.type==='checkbox')return'<label class="check"><input name="'+f.name+'" type="checkbox" '+(val?'checked':'')+'> '+esc(f.label)+'</label>';if(f.type==='textarea')return'<div class="field full"><label>'+esc(f.label)+(f.required?' *':'')+'</label><textarea name="'+f.name+'">'+esc(val)+'</textarea></div>';if(f.type==='select'){var opts=optionsFor(f);return'<div class="field"><label>'+esc(f.label)+(f.required?' *':'')+'</label><select name="'+f.name+'"><option value="">— اختر —</option>'+opts.map(function(x){return'<option value="'+esc(x[0])+'" '+(String(x[0])===String(val)?'selected':'')+'>'+esc(x[1])+'</option>'}).join('')+'</select></div>'}return'<div class="field '+(f.type==='text'&&/notes|subject|description/.test(f.name)?'full':'')+'"><label>'+esc(f.label)+(f.required?' *':'')+'</label><input name="'+f.name+'" type="'+esc(f.type)+'" value="'+esc(val)+'" '+(f.type==='number'?'step="any"':'')+'></div>'}
function formValues(form,fields){var o={};fields.forEach(function(f){var el=form.elements[f.name];if(!el)return;var v=f.type==='checkbox'?el.checked:el.value.trim();if(f.type==='number')v=v===''?null:Number(v);if(f.type==='select'&&v!==''&&/(_id|assigned_to|delivered_by|receiver_id|user_id)$/.test(f.name)&&!/^tmp-/.test(v))v=Number(v);o[f.name]=v===''?null:v});return o}
function endpoint(entity,id,caseId){if(entity==='case_stages')return id?'/api/stages/'+remoteId(id):'/api/cases/'+remoteId(caseId)+'/stages';return'/api/'+({session_secretaries:'secretaries'}[entity]||entity)+(id?'/'+remoteId(id):'')}
function openForm(entity,id,preset){var sc=SCHEMAS[entity];if(!sc)return;var rec=id?getBy(entity,id):null,vals=Object.assign({},rec||{},preset||{}),caseId=(preset||{})._case_id||(rec&&rec.case_id),fields=schemaFields(entity,caseId);sheet=true;var mode=id?'تعديل ':'إضافة ';app.insertAdjacentHTML('beforeend','<section class="sheet"><div class="sheet-head"><h2>'+mode+esc(sc.title)+'</h2><button class="icon-btn" data-close-sheet>✕</button></div><div class="sheet-body"><form id="entity-form" class="form-grid">'+fields.map(function(f){return fieldHtml(f,vals[f.name])}).join('')+'</form><div id="form-error" class="error hidden"></div><div class="form-actions"><button class="primary" data-save-form>حفظ</button><button class="secondary" data-close-sheet>إلغاء</button></div><div class="hint">يتم الحفظ على الهاتف فورًا ثم المزامنة مع برنامج المكتب.</div></div></section>');document.querySelector('[data-save-form]').onclick=async function(){var b=this,e=document.getElementById('form-error'),v=formValues(document.getElementById('entity-form'),fields),miss=fields.find(function(f){return f.required&&(v[f.name]==null||v[f.name]==='')});if(miss){e.textContent=miss.label+' مطلوب';e.classList.remove('hidden');return}b.disabled=true;try{if(entity==='users'&&id){var pw=v.password;delete v.password;delete v.username;await enqueueMutation('PUT',endpoint(entity,id),v);if(pw)await enqueueMutation('POST','/api/users/'+remoteId(id)+'/password',{password:pw})}else{var temp=id?null:tempId();await enqueueMutation(id?'PUT':'POST',endpoint(entity,id,caseId),v,temp)}closeSheet()}catch(x){e.textContent=x.message;e.classList.remove('hidden');b.disabled=false}}}
function closeSheet(){var s=document.querySelector('.sheet');if(s)s.remove();sheet=false;render()}
async function documentForm(caseId,clientId){sheet=true;app.insertAdjacentHTML('beforeend','<section class="sheet"><div class="sheet-head"><h2>رفع مستند</h2><button class="icon-btn" data-close-sheet>✕</button></div><div class="sheet-body"><div class="field"><label>عنوان المستند</label><input id="doc-title"></div><div class="field"><label>اختر الملف أو صوّره</label><input id="doc-file" type="file" accept="image/*,application/pdf,.doc,.docx,.xls,.xlsx" capture="environment"></div><div id="form-error" class="error hidden"></div><div class="form-actions"><button class="primary" id="doc-save">رفع</button><button class="secondary" data-close-sheet>إلغاء</button></div><div class="hint">الحد الأقصى من الموبايل 20 ميجابايت. الملف يُشفّر أثناء النقل.</div></div></section>');document.getElementById('doc-save').onclick=async function(){var f=document.getElementById('doc-file').files[0],e=document.getElementById('form-error');if(!f){e.textContent='اختر ملفًا';e.classList.remove('hidden');return}if(f.size>20*1024*1024){e.textContent='الملف أكبر من 20 ميجابايت';e.classList.remove('hidden');return}this.disabled=true;try{var data=await new Promise(function(resolve,reject){var r=new FileReader();r.onload=function(){resolve(String(r.result).split(',')[1])};r.onerror=reject;r.readAsDataURL(f)}),body={case_id:caseId||null,client_id:clientId||null,title:document.getElementById('doc-title').value.trim()||f.name,filename:f.name,mime:f.type||'application/octet-stream',size:f.size,data:data};await enqueueMutation('POST','/api/documents',body,tempId());closeSheet()}catch(x){e.textContent=x.message;e.classList.remove('hidden');this.disabled=false}}}
function decisionForm(id){var h=getBy('hearings',id),c=getBy('cases',h.case_id)||{};sheet=true;app.insertAdjacentHTML('beforeend','<section class="sheet"><div class="sheet-head"><h2>تسجيل نتيجة الجلسة</h2><button class="icon-btn" data-close-sheet>✕</button></div><div class="sheet-body"><div class="card"><h3>'+esc(c.subject||'')+'</h3><div class="meta">جلسة '+fmtDate(h.date)+'</div></div><div class="field"><label>القرار *</label><textarea id="decision"></textarea></div><div class="field"><label>الجلسة القادمة</label><input id="next-date" type="date"></div><div class="field"><label>الساعة</label><input id="next-time" type="time"></div><div id="form-error" class="error hidden"></div><div class="form-actions"><button class="primary" id="decision-save">حفظ ومزامنة</button><button class="secondary" data-close-sheet>إلغاء</button></div></div></section>');document.getElementById('decision-save').onclick=async function(){var d=document.getElementById('decision').value.trim(),e=document.getElementById('form-error');if(!d){e.textContent='اكتب القرار';e.classList.remove('hidden');return}var it={uid:uid(),op:'decision',hearing_id:Number(id),decision:d,next_date:document.getElementById('next-date').value||null,next_time:document.getElementById('next-time').value||null};outbox.push(it);optimistic(pack,{op:'mutate',method:'POST',path:'/api/hearings/'+id+'/decision',body:{decision:d}});await saveState();closeSheet();sync(false)}}
function officeSettingsForm(){var s=pack.settings||{};sheet=true;app.insertAdjacentHTML('beforeend','<section class="sheet"><div class="sheet-head"><h2>بيانات المكتب</h2><button class="icon-btn" data-close-sheet>✕</button></div><div class="sheet-body"><div class="form-grid"><div class="field"><label>اسم المكتب</label><input id="office-name" value="'+esc(s.office_name||'')+'"></div><div class="field"><label>العنوان</label><input id="office-address" value="'+esc(s.office_address||'')+'"></div><div class="field"><label>الهاتف</label><input id="office-phone" value="'+esc(s.office_phone||'')+'"></div></div><div class="form-actions"><button class="primary" id="office-save">حفظ</button><button class="secondary" data-close-sheet>إلغاء</button></div></div></section>');document.getElementById('office-save').onclick=async function(){await enqueueMutation('PUT','/api/settings',{office_name:document.getElementById('office-name').value,office_address:document.getElementById('office-address').value,office_phone:document.getElementById('office-phone').value});closeSheet()}}

