app.addEventListener('click',async function(e){var x=e.target.closest('[data-page]');if(x){page=x.dataset.page;selected=null;q='';detailTab='summary';return render()}if(e.target.closest('[data-sync]'))return sync(true);if(e.target.closest('[data-back]')){selected=null;detailTab='summary';return render()}x=e.target.closest('[data-open-case]');if(x){page='cases';selected=x.dataset.openCase;detailTab='summary';return render()}x=e.target.closest('[data-open-client]');if(x){page='clients';selected=x.dataset.openClient;return render()}x=e.target.closest('[data-detail-tab]');if(x){detailTab=x.dataset.detailTab;return render()}x=e.target.closest('[data-add]');if(x){if(x.dataset.add==='documents')return documentForm();return openForm(x.dataset.add,null,{})}x=e.target.closest('[data-edit]');if(x){var p=x.dataset.edit.split(':');return openForm(p[0],p.slice(1).join(':'),{})}x=e.target.closest('[data-add-related]');if(x){var r=x.dataset.addRelated.split(':'),pre={case_id:r[1]};return openForm(r[0],null,pre)}x=e.target.closest('[data-add-stage]');if(x)return openForm('case_stages',null,{_case_id:x.dataset.addStage,degree:'استئناف',make_current:true});x=e.target.closest('[data-add-document]');if(x)return documentForm(x.dataset.addDocument,null);x=e.target.closest('[data-add-client-document]');if(x)return documentForm(null,x.dataset.addClientDocument);x=e.target.closest('[data-decision]');if(x)return decisionForm(x.dataset.decision);x=e.target.closest('[data-download]');if(x)return enqueueDownload(x.dataset.download);x=e.target.closest('[data-task-done]');if(x)return enqueueMutation('POST','/api/tasks/'+remoteId(x.dataset.taskDone)+'/status',{status:'منجزة'});x=e.target.closest('[data-delete]');if(x){var d=x.dataset.delete.split(':'),kind=d[0],id=d.slice(1).join(':');if(confirm('متأكد من الحذف؟ العنصر سينتقل إلى سلة المحذوفات.'))await enqueueMutation('DELETE',deletePath(kind,id),{});return}x=e.target.closest('[data-restore]');if(x){await enqueueMutation('POST','/api/trash/'+x.dataset.restore+'/restore',{});return}x=e.target.closest('[data-close-sheet]');if(x)return closeSheet();x=e.target.closest('[data-note]');if(x){e.preventDefault();notes.splice(Number(x.dataset.note),1);await saveState();return render()}if(e.target.closest('[data-office-settings]'))return officeSettingsForm();if(e.target.closest('[data-unlink]')){if(confirm('سيتم مسح نسخة بيانات المكتب والتعديلات التي لم تصل. هل تريد المتابعة؟'))await wipe('تم فصل الهاتف')}});

