async function start(){if(!window.crypto||!crypto.subtle){app.innerHTML='<div class="splash"><div><h1>المتصفح قديم</h1><p>حدّث Chrome أو Safari لتشغيل ميزان.</p></div></div>';return}if('serviceWorker'in navigator&&(location.protocol==='https:'||/^(localhost|127\.0\.0\.1)$/.test(location.hostname)))navigator.serviceWorker.register('sw.js').catch(function(){});try{T=JSON.parse(lsGet('t')||'null')}catch(e){T=null}pack=await kvGet('pack',null);outbox=await kvGet('outbox',[]);notes=await kvGet('notes',[]);lastSync=await kvGet('last',0);var m=/[#&]c=([A-Za-z0-9-]{9,13})/.exec(location.hash);if(m){history.replaceState(null,'',location.pathname+location.search);if(!T||confirm('الهاتف مربوط بالفعل. هل تريد ربطه بالمكتب الجديد؟'))return renderPair(m[1].replace(/-/g,''))}render();if(T&&!DEMO)sync(false);if(!DEMO){setInterval(function(){if(!document.hidden)sync(false)},SYNC_MS);document.addEventListener('visibilitychange',function(){if(!document.hidden&&Date.now()-lastSync>60000)sync(false)});window.addEventListener('online',function(){sync(false)})}}
start();
